def get_max_nested_parens(paren_string: str) -> List[int]:
    """ This is a helper function that takes in a string with multiple groups with nested parentheses separated by spaces.
    Returns a list of maxes corresponding to each group.
    """
    if not paren_string:
        return []

    result_list = []

    for paren_group in paren_string.split(' '):
        if not paren_group:
            continue

        max_nested_parens = 0
        count_of_group = 0
        count_of_each_group = 0

        for char in paren_group:
            if char == '(':
                count_of_group += 1
                max_nested_parens = max(max_nested_parens, count_of_each_group)
            elif char == ')':
                count_of_group -= 1
                count_of_each_group += 1

        result_list.append(max_nested_parens)

    return result_list

