def partition(numbers: List[float], pivot_value: float) -> List[float]:
    """ Partition a list of numbers in two parts based on given pivot value
    >>> partition([1, 2, 3, 20, 4, 10], 1)
    [[1, 2], [4, 20, 3, 10]]
    """
    smaller, larger = [], []
    for x in numbers:
        if x < pivot_value:
            smaller.append(x)
        else:
            larger.append(x)
    return smaller, larger


